[[vk::binding(0, 0)]] RWTexture2D<float4> gOutput;
[[vk::binding(1, 0)]] cbuffer Host {
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};
[[vk::binding(2, 0)]] RaytracingAccelerationStructure gScene;

struct Payload { float4 c; };

[shader("raygeneration")]
void RayGen()
{
    uint2 idx = DispatchRaysIndex().xy;
    uint2 dim = DispatchRaysDimensions().xy;
    float2 uv = (float2(idx) + 0.5) / float2(dim);
    float2 ndc = uv * 2.0 - 1.0;
    ndc.y = -ndc.y;
    float aspect = float(dim.x) / float(dim.y);
    float3 dir = normalize(float3(ndc.x * aspect, ndc.y, 2.0));

    RayDesc ray;
    ray.Origin = float3(0, 1, -4);
    ray.TMin = 0.001;
    ray.Direction = dir;
    ray.TMax = 100.0;

    Payload p;
    p.c = float4(0, 0, 0, 1);
    TraceRay(gScene, RAY_FLAG_NONE, 0xFF, 0, 0, 0, ray, p);
    gOutput[idx] = p.c;
}

struct Payload { float4 c; };
[shader("miss")]
void Miss(inout Payload p)
{
    float3 dir = WorldRayDirection();
    float sky = saturate(0.5 + 0.5 * dir.y);
    p.c = float4(lerp(float3(0.6, 0.8, 1.0), float3(0.2, 0.4, 0.9), sky), 1.0);
}

struct ShadowPayload { float shadow; };
[shader("miss")]
void ShadowMiss(inout ShadowPayload p)
{
    p.shadow = 1.0;
}

[[vk::binding(1, 0)]] cbuffer Host {
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};
[[vk::binding(2, 0)]] RaytracingAccelerationStructure gScene;

struct Payload { float4 c; };
struct ShadowPayload { float shadow; };

[shader("closesthit")]
void ClosestHit(inout Payload p, in BuiltInTriangleIntersectionAttributes a)
{
    float t = time_sim_ms * 0.001;
    float3 hitPos = WorldRayOrigin() + WorldRayDirection() * RayTCurrent();
    float3 normal = normalize(float3(0, 1, 0));
    float3 lightPos = float3(sin(t) * 3.0, 4.0, cos(t) * 3.0);
    float3 lightDir = normalize(lightPos - hitPos);
    RayDesc shadowRay;
    shadowRay.Origin = hitPos + normal * 0.01;
    shadowRay.TMin = 0.001;
    shadowRay.Direction = lightDir;
    shadowRay.TMax = length(lightPos - hitPos);
    ShadowPayload sp;
    sp.shadow = 0.0;
    TraceRay(gScene, RAY_FLAG_ACCEPT_FIRST_HIT_AND_END_SEARCH, 0xFF, 0, 0, 1, shadowRay, sp);
    float diff = max(dot(normal, lightDir), 0.0);
    float3 baseColor = float3(0.7, 0.7, 0.7);
    float3 col = baseColor * (0.2 + 0.8 * diff * sp.shadow);
    p.c = float4(col, 1.0);
}
